 {std::vector<uint8_t> prefix(fixtureData.begin(),fixtureData.begin()+readbackTarget::BYTES);Reader r{prefix};Hash h;assert(diag::verify(r,h,buf,progress,readbackTarget::BYTES,readbackTarget::SHA,false).ok);++cases;Reader fail{prefix};fail.failAt=901120;fail.returnBytes=0;fail.error=EIO;Hash fh;auto bad=diag::verify(fail,fh,buf,progress,readbackTarget::BYTES,readbackTarget::SHA,false);assert(!bad.ok&&bad.offset==901120&&bad.requested==4096&&bad.received==0&&bad.error==EIO&&fail.calls==221);++cases;}
