 struct Writer {std::vector<uint8_t> bytes;unsigned calls=0;size_t failAt=SIZE_MAX;int32_t returned=0;int error=0;diag::Write write(const uint8_t* p,size_t n){++calls;if(bytes.size()==failAt)return {returned,error};bytes.insert(bytes.end(),p,p+n);return {int32_t(n),0};}};
 for(unsigned fault=0;fault<5;++fault){Writer w;if(fault){w.failAt=8192;w.returned=fault==1?4095:fault==2?-1:4096;w.error=fault==1?0:EIO;}auto r=diag::writePrefix(w,buf,[&](uint32_t p){return fault!=4||p<4096;});assert(r.ok==(fault==0));if(!fault){assert(w.bytes.size()==diag::CHECKPOINT&&std::equal(w.bytes.begin(),w.bytes.end(),fixtureData.begin()));Reader rd{w.bytes};Hash h;assert(diag::verify(rd,h,buf,progress,diag::CHECKPOINT,diag::PREFIX_SHA,false).ok);}else if(fault==4){assert(!strcmp(r.cause,"time-limit")&&r.offset==4096&&w.calls==1);}else{assert(!strcmp(r.cause,"write")&&r.offset==8192&&r.written==w.returned&&r.error==w.error&&w.calls==3);}++cases;}
